1	/** Pure replay fold and strict decoders for durable completion-standard changes. */
2	
3	import type { SessionEvent } from '@deepseek-ai/dsh-session'
4	import { GoalId } from '@deepseek-ai/dsh-goal'
5	import { CheckId, isKebabCase, StandardId, VERIFICATION_CHANGE_VERSION } from './runtime.ts'
6	import type {
7	  CertificateIsolation,
8	  CheckResult,
9	  CheckStatus,
10	  CompletionStandardSnapshot,
11	  RelaxedCheck,
12	  RunExecutor,
13	  RunVerdict,
14	  StandardCheck,
15	  StandardRef,
16	  VerificationCertificate,
17	} from './types.ts'
18	import type {
19	  CertificateChangeMeta,
20	  DirectiveChangeMeta,
21	  FoldedVerification,
22	  RelaxationChangeMeta,
23	  StandardChangeMeta,
24	  StandardOperation,
25	  VerificationRunChangeMeta,
26	} from './domain.ts'
27	
28	const OPERATIONS: ReadonlySet<StandardOperation> = new Set(['author', 'extend'])
29	const ISOLATIONS: ReadonlySet<CertificateIsolation> = new Set(['none', 'process', 'host'])
30	const EXECUTORS: ReadonlySet<RunExecutor> = new Set(['runner', 'agent-reported'])
31	const VERDICTS: ReadonlySet<RunVerdict> = new Set(['passed', 'failed', 'tampered'])
32	const CERTIFIED_STATUSES: ReadonlySet<CheckStatus> = new Set(['pass'])
33	const RUN_STATUSES: ReadonlySet<CheckStatus> = new Set(['pass', 'fail'])
34	const RUN_KEYS = ['attempt', 'executor', 'isolation', 'kind', 'recordedAt', 'results', 'standard', 'version']
35	const HEX_DIGEST = /^[0-9a-f]+$/
36	
37	/** Mutable accumulator kept private to the pure fold. */
38	export interface VerificationFoldState {
39	  standard: CompletionStandardSnapshot | undefined
40	  certificate: VerificationCertificate | undefined
41	  directivesIssued: number
42	  runsRecorded: number
43	  lastRun: VerificationRunChangeMeta | undefined
44	  createdAt: number | undefined
45	  updatedAt: number | undefined
46	  lastRef: StandardRef | undefined
47	  seenStandardIds: Set<CompletionStandardSnapshot['id']>
48	}
49	
50	/**
51	 * Attempt number the next run of one standard must carry. Authorship never
52	 * reuses a standard id, so the runs of one standard are contiguous in the log
53	 * and the last one carries their count.
54	 * @param state - fold accumulator covering every prior event.
55	 * @param id - standard the next run covers.
56	 * @returns one plus the runs already recorded for that standard id.
57	 */
58	export function nextRunAttempt(state: VerificationFoldState, id: CompletionStandardSnapshot['id']): number {
59	  const last = state.lastRun
60	  return (last !== undefined && last.standard.id === id ? last.attempt : 0) + 1
61	}
62	
63	/**
64	 * Build an empty replay accumulator.
65	 * @returns mutable state with no current standard or prior ref.
66	 */
67	export function emptyVerificationFoldState(): VerificationFoldState {
68	  return {
69	    standard: undefined,
70	    certificate: undefined,
71	    directivesIssued: 0,
72	    runsRecorded: 0,
73	    lastRun: undefined,
74	    createdAt: undefined,
75	    updatedAt: undefined,
76	    lastRef: undefined,
77	    seenStandardIds: new Set(),
78	  }
79	}
80	
81	// Strict per-domain decoders keep their own guards (the goal fold is the template).
82	/* jscpd:ignore-start */
83	/** Whether a value is a JSON record rather than an array. */
84	function isRecord(value: unknown): value is Record<string, unknown> {
85	  return typeof value === 'object' && value !== null && !Array.isArray(value)
86	}
87	
88	/** Require one positive safe integer. */
89	function positiveInteger(value: unknown, field: string): number {
90	  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 1) {
91	    throw new Error(`verification change ${field} must be a positive safe integer`)
92	  }
93	  return value
94	}
95	
96	/** Require one non-negative safe integer. */
97	function nonNegativeInteger(value: unknown, field: string): number {
98	  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 0) {
99	    throw new Error(`verification change ${field} must be a non-negative safe integer`)
100	  }
101	  return value
102	}
103	/* jscpd:ignore-end */
104	
105	/** Require one lowercase hex digest. */
106	function hexDigest(value: unknown, field: string): string {
107	  if (typeof value !== 'string' || !HEX_DIGEST.test(value)) {
108	    throw new Error(`verification change ${field} must be a lowercase hex digest`)
109	  }
110	  return value
111	}
112	
113	/** Require one non-empty trim-normalized string. */
114	function normalizedText(value: unknown, field: string): string {
115	  if (typeof value !== 'string' || value.trim().length === 0 || value !== value.trim()) {
116	    throw new Error(`verification change ${field} must be non-empty and normalized`)
117	  }
118	  return value
119	}
120	
121	/** Require an exact sorted key set. */
122	function requireKeys(value: Record<string, unknown>, expected: readonly string[], subject: string): void {
123	  const keys = Object.keys(value).sort().join(',')
124	  const wanted = [...expected].sort().join(',')
125	  if (keys !== wanted) {
126	    throw new Error(`verification change ${subject} must have exactly ${wanted} fields`)
127	  }
128	}
129	
130	/** Decode and validate one check. */
131	function decodeCheck(value: unknown, subject: string): StandardCheck {
132	  if (!isRecord(value)) throw new Error(`verification change ${subject} must be a record`)
133	  requireKeys(value, ['id', 'outcome', 'run'], subject)
134	  const rawId = value['id']
135	  if (typeof rawId !== 'string' || !isKebabCase(rawId)) {
136	    throw new Error(`verification change ${subject}.id must be lower-kebab-case`)
137	  }
138	  return {
139	    id: CheckId(rawId),
140	    outcome: normalizedText(value['outcome'], `${subject}.outcome`),
141	    run: normalizedText(value['run'], `${subject}.run`),
142	  }
143	}
144	
145	/** Decode and validate one relaxed entry. */
146	function decodeRelaxed(value: unknown, subject: string): RelaxedCheck {
147	  if (!isRecord(value)) throw new Error(`verification change ${subject} must be a record`)
148	  requireKeys(value, ['check', 'evidence'], subject)
149	  return {
150	    check: decodeCheck(value['check'], `${subject}.check`),
151	    evidence: normalizedText(value['evidence'], `${subject}.evidence`),
152	  }
153	}
154	
155	/** Decode and validate one full standard snapshot. */
156	function decodeSnapshot(value: unknown): CompletionStandardSnapshot {
157	  if (!isRecord(value)) throw new Error('verification change standard must be a record')
158	  requireKeys(value, ['checks', 'goalId', 'id', 'relaxed', 'revision'], 'standard')
159	  if (typeof value['id'] !== 'string' || value['id'].length === 0) {
160	    throw new Error('verification change standard.id must be a non-empty string')
161	  }
162	  if (typeof value['goalId'] !== 'string' || value['goalId'].length === 0) {
163	    throw new Error('verification change standard.goalId must be a non-empty string')
164	  }
165	  if (!Array.isArray(value['checks'])) throw new Error('verification change standard.checks must be an array')
166	  if (!Array.isArray(value['relaxed'])) throw new Error('verification change standard.relaxed must be an array')
167	  const checks = value['checks'].map((check, index) => decodeCheck(check, `standard.checks[${index}]`))
168	  const relaxed = value['relaxed'].map((entry, index) => decodeRelaxed(entry, `standard.relaxed[${index}]`))
169	  const ids = new Set<string>()
170	  for (const check of checks) {
171	    if (ids.has(check.id)) throw new Error(`verification change standard.checks repeats id "${check.id}"`)
172	    ids.add(check.id)
173	  }
174	  for (const entry of relaxed) {
175	    if (ids.has(entry.check.id)) {
176	      throw new Error(`verification change standard.relaxed repeats id "${entry.check.id}"`)
177	    }
178	    ids.add(entry.check.id)
179	  }
180	  return {
181	    id: StandardId(value['id']),
182	    revision: positiveInteger(value['revision'], 'standard.revision'),
183	    goalId: GoalId(value['goalId']),
184	    checks,
185	    relaxed,
186	  }
187	}
188	
189	/** Decode and validate one standard ref. */
190	function decodeRef(value: unknown, subject: string): StandardRef {
191	  if (!isRecord(value)) throw new Error(`verification change ${subject} must be a record`)
192	  requireKeys(value, ['id', 'revision'], subject)
193	  if (typeof value['id'] !== 'string' || value['id'].length === 0) {
194	    throw new Error(`verification change ${subject}.id must be a non-empty string`)
195	  }
196	  return { id: StandardId(value['id']), revision: positiveInteger(value['revision'], `${subject}.revision`) }
197	}
198	
199	/** Decode one check result, admitting exactly the statuses its carrier allows. */
200	function decodeResult(
201	  value: unknown,
202	  subject: string,
203	  admitted: ReadonlySet<CheckStatus>,
204	  requirement: string,
205	): CheckResult {
206	  if (!isRecord(value)) throw new Error(`verification change ${subject} must be a record`)
207	  requireKeys(value, ['checkId', 'evidence', 'status'], subject)
208	  const rawCheckId = value['checkId']
209	  if (typeof rawCheckId !== 'string' || !isKebabCase(rawCheckId)) {
210	    throw new Error(`verification change ${subject}.checkId must be lower-kebab-case`)
211	  }
212	  const status = value['status'] as CheckStatus
213	  if (!admitted.has(status)) {
214	    throw new Error(`verification change ${subject}.status must be ${requirement}`)
215	  }
216	  return {
217	    checkId: CheckId(rawCheckId),
218	    status,
219	    evidence: normalizedText(value['evidence'], `${subject}.evidence`),
220	  }
221	}
222	
223	/** Decode one passing certificate result. */
224	function decodeCertificateResult(value: unknown, subject: string): CheckResult {
225	  return decodeResult(value, subject, CERTIFIED_STATUSES, '"pass" inside a certificate')
226	}
227	
228	/** Decode one recorded run result, passing or failing. */
229	function decodeRunResult(value: unknown, subject: string): CheckResult {
230	  return decodeResult(value, subject, RUN_STATUSES, '"pass" or "fail"')
231	}
232	
233	/**
234	 * The verdict one run payload carries, or the one its results decide. Absence
235	 * is not a gap: every verdict but `tampered` follows from the results, and a
236	 * payload that states nothing states no tamper.
237	 */
238	function decodeVerdict(value: unknown, results: readonly CheckResult[]): RunVerdict {
239	  if (value === undefined) return results.every(result => result.status === 'pass') ? 'passed' : 'failed'
240	  if (typeof value !== 'string' || !VERDICTS.has(value as RunVerdict)) {
241	    throw new Error('verification change run.verdict is invalid')
242	  }
243	  return value as RunVerdict
244	}
245	
246	/** Shared timestamp validation for standard-shaped changes. */
247	function decodeTimestamps(value: Record<string, unknown>): { createdAt: number; updatedAt: number } {
248	  const createdAt = nonNegativeInteger(value['createdAt'], 'createdAt')
249	  const updatedAt = nonNegativeInteger(value['updatedAt'], 'updatedAt')
250	  if (updatedAt < createdAt) throw new Error('verification change updatedAt cannot precede createdAt')
251	  return { createdAt, updatedAt }
252	}
253	
254	/** Require a self-declared payload version. */
255	function requireVersion(value: Record<string, unknown>): void {
256	  if (value['version'] !== VERIFICATION_CHANGE_VERSION) {
257	    throw new Error(`unsupported verification change version ${String(value['version'])}`)
258	  }
259	}
260	
261	/**
262	 * Decode a value that declares itself as a standard change. Unrelated values
263	 * return `undefined`; malformed standard changes fail replay loudly.
264	 * @param value - candidate durable payload.
265	 * @returns validated standard change or `undefined` for another value kind.
266	 */
267	export function decodeStandardChange(value: unknown): StandardChangeMeta | undefined {
268	  if (!isRecord(value) || value['kind'] !== 'verification/standard') return undefined
269	  requireVersion(value)
270	  requireKeys(value, ['createdAt', 'kind', 'operation', 'standard', 'updatedAt', 'version'], 'standard change')
271	  if (typeof value['operation'] !== 'string' || !OPERATIONS.has(value['operation'] as StandardOperation)) {
272	    throw new Error('verification change operation is invalid')
273	  }
274	  return {
275	    kind: 'verification/standard',
276	    version: VERIFICATION_CHANGE_VERSION,
277	    operation: value['operation'] as StandardOperation,
278	    standard: decodeSnapshot(value['standard']),
279	    ...decodeTimestamps(value),
280	  }
281	}
282	
283	/**
284	 * Decode a value that declares itself as a relaxation. Unrelated values
285	 * return `undefined`; malformed relaxations fail replay loudly.
286	 * @param value - candidate durable payload.
287	 * @returns validated relaxation or `undefined` for another value kind.
288	 */
289	export function decodeRelaxationChange(value: unknown): RelaxationChangeMeta | undefined {
290	  if (!isRecord(value) || value['kind'] !== 'verification/relaxation') return undefined
291	  requireVersion(value)
292	  requireKeys(value, ['checkId', 'createdAt', 'kind', 'standard', 'updatedAt', 'version'], 'relaxation')
293	  const rawCheckId = value['checkId']
294	  if (typeof rawCheckId !== 'string' || !isKebabCase(rawCheckId)) {
295	    throw new Error('verification change relaxation checkId must be lower-kebab-case')
296	  }
297	  const standard = decodeSnapshot(value['standard'])
298	  const last = standard.relaxed[standard.relaxed.length - 1]
299	  if (last === undefined || last.check.id !== rawCheckId) {
300	    throw new Error('verification change relaxation must end the snapshot relaxed list with its check')
301	  }
302	  return {
303	    kind: 'verification/relaxation',
304	    version: VERIFICATION_CHANGE_VERSION,
305	    checkId: CheckId(rawCheckId),
306	    standard,
307	    ...decodeTimestamps(value),
308	  }
309	}
310	
311	/**
312	 * Decode a value that declares itself as a run. Unrelated values return
313	 * `undefined`; malformed runs fail replay loudly.
314	 * @param value - candidate durable payload.
315	 * @returns validated run or `undefined` for another value kind.
316	 */
317	export function decodeRunChange(value: unknown): VerificationRunChangeMeta | undefined {
318	  if (!isRecord(value) || value['kind'] !== 'verification/run') return undefined
319	  requireVersion(value)
320	  const treeHash = value['treeHash']
321	  const optional = [
322	    ...treeHash === undefined ? [] : ['treeHash'],
323	    ...value['verdict'] === undefined ? [] : ['verdict'],
324	  ]
325	  requireKeys(value, [...RUN_KEYS, ...optional], 'run')
326	  if (typeof value['isolation'] !== 'string' || !ISOLATIONS.has(value['isolation'] as CertificateIsolation)) {
327	    throw new Error('verification change run.isolation is invalid')
328	  }
329	  if (typeof value['executor'] !== 'string' || !EXECUTORS.has(value['executor'] as RunExecutor)) {
330	    throw new Error('verification change run.executor is invalid')
331	  }
332	  if (!Array.isArray(value['results']) || value['results'].length === 0) {
333	    throw new Error('verification change run.results must be a non-empty array')
334	  }
335	  const results = value['results'].map((result, index) => decodeRunResult(result, `run.results[${index}]`))
336	  return {
337	    kind: 'verification/run',
338	    version: VERIFICATION_CHANGE_VERSION,
339	    standard: decodeRef(value['standard'], 'run.standard'),
340	    attempt: positiveInteger(value['attempt'], 'run.attempt'),
341	    isolation: value['isolation'] as CertificateIsolation,
342	    executor: value['executor'] as RunExecutor,
343	    verdict: decodeVerdict(value['verdict'], results),
344	    results,
345	    ...treeHash === undefined ? {} : { treeHash: hexDigest(treeHash, 'run.treeHash') },
346	    recordedAt: nonNegativeInteger(value['recordedAt'], 'run.recordedAt'),
347	  }
348	}
349	
350	/**
351	 * Decode a value that declares itself as a certificate. Unrelated values
352	 * return `undefined`; malformed certificates fail replay loudly.
353	 * @param value - candidate durable payload.
354	 * @returns validated certificate or `undefined` for another value kind.
355	 */
356	export function decodeCertificateChange(value: unknown): CertificateChangeMeta | undefined {
357	  if (!isRecord(value) || value['kind'] !== 'verification/certificate') return undefined
358	  requireVersion(value)
359	  requireKeys(value, ['certificate', 'kind', 'version'], 'certificate')
360	  const certificate = value['certificate']
361	  if (!isRecord(certificate)) throw new Error('verification change certificate must be a record')
362	  requireKeys(certificate, ['executor', 'goalId', 'isolation', 'recordedAt', 'results', 'standard'], 'certificate')
363	  if (typeof certificate['goalId'] !== 'string' || certificate['goalId'].length === 0) {
364	    throw new Error('verification change certificate.goalId must be a non-empty string')
365	  }
366	  if (typeof certificate['isolation'] !== 'string'
367	    || !ISOLATIONS.has(certificate['isolation'] as CertificateIsolation)) {
368	    throw new Error('verification change certificate.isolation is invalid')
369	  }
370	  if (typeof certificate['executor'] !== 'string' || !EXECUTORS.has(certificate['executor'] as RunExecutor)) {
371	    throw new Error('verification change certificate.executor is invalid')
372	  }
373	  if (!Array.isArray(certificate['results']) || certificate['results'].length === 0) {
374	    throw new Error('verification change certificate.results must be a non-empty array')
375	  }
376	  return {
377	    kind: 'verification/certificate',
378	    version: VERIFICATION_CHANGE_VERSION,
379	    certificate: {
380	      standard: decodeRef(certificate['standard'], 'certificate.standard'),
381	      goalId: GoalId(certificate['goalId']),
382	      isolation: certificate['isolation'] as CertificateIsolation,
383	      executor: certificate['executor'] as RunExecutor,
384	      results: certificate['results'].map((result, index) =>
385	        decodeCertificateResult(result, `certificate.results[${index}]`)),
386	      recordedAt: nonNegativeInteger(certificate['recordedAt'], 'certificate.recordedAt'),
387	    },
388	  }
389	}
390	
391	/**
392	 * Decode a value that declares itself as a directive. Unrelated values
393	 * return `undefined`; malformed directives fail replay loudly.
394	 * @param value - candidate durable payload.
395	 * @returns validated directive or `undefined` for another value kind.
396	 */
397	export function decodeDirectiveChange(value: unknown): DirectiveChangeMeta | undefined {
398	  if (!isRecord(value) || value['kind'] !== 'verification/directive') return undefined
399	  requireVersion(value)
400	  requireKeys(value, ['detail', 'issuedAt', 'kind', 'rootCause', 'standard', 'version'], 'directive')
401	  return {
402	    kind: 'verification/directive',
403	    version: VERIFICATION_CHANGE_VERSION,
404	    standard: decodeRef(value['standard'], 'directive.standard'),
405	    rootCause: normalizedText(value['rootCause'], 'directive.rootCause'),
406	    detail: normalizedText(value['detail'], 'directive.detail'),
407	    issuedAt: nonNegativeInteger(value['issuedAt'], 'issuedAt'),
408	  }
409	}
410	
411	/** Require two checks to be identical field-for-field. */
412	function requireSameCheck(previous: StandardCheck, next: StandardCheck, subject: string): void {
413	  if (previous.id !== next.id || previous.outcome !== next.outcome || previous.run !== next.run) {
414	    throw new Error(`verification change ${subject} must preserve the existing check "${previous.id}"`)
415	  }
416	}
417	
418	/** Require the relaxed list to preserve an existing prefix exactly. */
419	function requireSameRelaxed(previous: readonly RelaxedCheck[], next: readonly RelaxedCheck[], subject: string): void {
420	  for (const [index, entry] of previous.entries()) {
421	    const candidate = next[index]
422	    if (candidate === undefined || candidate.evidence !== entry.evidence) {
423	      throw new Error(`verification change ${subject} must preserve the existing relaxation of "${entry.check.id}"`)
424	    }
425	    requireSameCheck(entry.check, candidate.check, subject)
426	  }
427	}
428	
429	/** Require one exact next revision of the current standard for the same goal. */
430	function requireNextRevision(
431	  current: CompletionStandardSnapshot,
432	  next: CompletionStandardSnapshot,
433	  operation: string,
434	): void {
435	  if (next.id !== current.id || next.revision !== current.revision + 1 || next.goalId !== current.goalId) {
436	    throw new Error(`verification ${operation} must advance the current standard by one revision for its goal`)
437	  }
438	}
439	
440	/** Require preserved creation time and monotone update time. */
441	function requireTimestampContinuity(
442	  state: VerificationFoldState,
443	  createdAt: number,
444	  updatedAt: number,
445	  operation: string,
446	): void {
447	  /* v8 ignore next -- a current standard established by this fold always has an updatedAt */
448	  if (state.updatedAt === undefined) throw new Error('current standard fold lacks updatedAt')
449	  if (createdAt !== state.createdAt || updatedAt < state.updatedAt) {
450	    throw new Error(`verification ${operation} does not preserve the current timestamps`)
451	  }
452	}
453	
454	/** Validate and apply one standard change (author or extend). */
455	function applyStandardChange(state: VerificationFoldState, change: StandardChangeMeta): void {
456	  const next = change.standard
457	  if (change.operation === 'author') {
458	    if (next.revision !== 1 || next.relaxed.length !== 0 || next.checks.length === 0
459	      || state.seenStandardIds.has(next.id)
460	      || (state.standard !== undefined && state.standard.goalId === next.goalId)) {
461	      throw new Error('verification author requires a fresh revision-one standard for a new goal')
462	    }
463	    state.seenStandardIds.add(next.id)
464	  } else {
465	    const current = state.standard
466	    if (current === undefined) throw new Error('verification extend requires a current standard')
467	    requireNextRevision(current, next, change.operation)
468	    requireTimestampContinuity(state, change.createdAt, change.updatedAt, change.operation)
469	    if (next.checks.length <= current.checks.length) {
470	      throw new Error('verification extend must add at least one check')
471	    }
472	    for (const [index, check] of current.checks.entries()) {
473	      requireSameCheck(check, next.checks[index] as StandardCheck, change.operation)
474	    }
475	    if (next.relaxed.length !== current.relaxed.length) {
476	      throw new Error('verification extend cannot change relaxations')
477	    }
478	    requireSameRelaxed(current.relaxed, next.relaxed, change.operation)
479	  }
480	  state.standard = next
481	  state.certificate = undefined
482	  state.createdAt = change.createdAt
483	  state.updatedAt = change.updatedAt
484	  state.lastRef = { id: next.id, revision: next.revision }
485	}
486	
487	/** Validate and apply one relaxation. */
488	function applyRelaxationChange(state: VerificationFoldState, change: RelaxationChangeMeta): void {
489	  const current = state.standard
490	  if (current === undefined) throw new Error('verification relaxation requires a current standard')
491	  const next = change.standard
492	  requireNextRevision(current, next, 'relaxation')
493	  requireTimestampContinuity(state, change.createdAt, change.updatedAt, 'relaxation')
494	  const removed = current.checks.find(check => check.id === change.checkId)
495	  if (removed === undefined) {
496	    throw new Error(`verification relaxation names unknown check "${change.checkId}"`)
497	  }
498	  const remaining = current.checks.filter(check => check.id !== change.checkId)
499	  if (next.checks.length !== remaining.length) {
500	    throw new Error('verification relaxation must remove exactly its named check')
501	  }
502	  for (const [index, check] of remaining.entries()) {
503	    requireSameCheck(check, next.checks[index] as StandardCheck, 'relaxation')
504	  }
505	  if (next.relaxed.length !== current.relaxed.length + 1) {
506	    throw new Error('verification relaxation must append exactly one relaxed entry')
507	  }
508	  requireSameRelaxed(current.relaxed, next.relaxed, 'relaxation')
509	  const appended = next.relaxed[next.relaxed.length - 1] as RelaxedCheck
510	  requireSameCheck(removed, appended.check, 'relaxation')
511	  state.standard = next
512	  state.certificate = undefined
513	  state.createdAt = change.createdAt
514	  state.updatedAt = change.updatedAt
515	  state.lastRef = { id: next.id, revision: next.revision }
516	}
517	
518	/** Require one result per active check, in the standard's check order. */
519	function requireResultsCover(
520	  current: CompletionStandardSnapshot,
521	  results: readonly CheckResult[],
522	  subject: string,
523	): void {
524	  if (results.length !== current.checks.length) {
525	    throw new Error(`verification ${subject} must carry one result per active check`)
526	  }
527	  for (const [index, check] of current.checks.entries()) {
528	    if (results[index]?.checkId !== check.id) {
529	      throw new Error(`verification ${subject} result ${index} must answer check "${check.id}"`)
530	    }
531	  }
532	}
533	
534	/** Validate and apply one executed run. */
535	function applyRunChange(state: VerificationFoldState, change: VerificationRunChangeMeta): void {
536	  const current = state.standard
537	  if (current === undefined) throw new Error('verification run requires a current standard')
538	  if (change.standard.id !== current.id || change.standard.revision !== current.revision) {
539	    throw new Error('verification run must cover the exact current standard revision')
540	  }
541	  requireResultsCover(current, change.results, 'run')
542	  const allPassed = change.results.every(result => result.status === 'pass')
543	  if (change.verdict === 'passed' && !allPassed) {
544	    throw new Error('verification run cannot record verdict "passed" with a failing result')
545	  }
546	  if (change.verdict === 'failed' && allPassed) {
547	    throw new Error('verification run cannot record verdict "failed" with every result passing')
548	  }
549	  /* v8 ignore next -- a current standard established by this fold always has an updatedAt */
550	  if (state.updatedAt === undefined) throw new Error('current standard fold lacks updatedAt')
551	  if (change.recordedAt < state.updatedAt) {
552	    throw new Error('verification run cannot precede the current standard update')
553	  }
554	  const expected = nextRunAttempt(state, current.id)
555	  if (change.attempt !== expected) {
556	    throw new Error(`verification run must number attempt ${expected} for standard "${current.id}"`)
557	  }
558	  state.runsRecorded += 1
559	  state.lastRun = change
560	}
561	
562	/** Validate and apply one certificate. */
563	function applyCertificateChange(state: VerificationFoldState, change: CertificateChangeMeta): void {
564	  const current = state.standard
565	  if (current === undefined) throw new Error('verification certificate requires a current standard')
566	  const certificate = change.certificate
567	  if (certificate.standard.id !== current.id || certificate.standard.revision !== current.revision
568	    || certificate.goalId !== current.goalId) {
569	    throw new Error('verification certificate must cover the exact current standard revision')
570	  }
571	  requireResultsCover(current, certificate.results, 'certificate')
572	  /* v8 ignore next -- a current standard established by this fold always has an updatedAt */
573	  if (state.updatedAt === undefined) throw new Error('current standard fold lacks updatedAt')
574	  if (certificate.recordedAt < state.updatedAt) {
575	    throw new Error('verification certificate cannot precede the current standard update')
576	  }
577	  state.certificate = certificate
578	}
579	
580	/** Validate and apply one directive record. */
581	function applyDirectiveChange(state: VerificationFoldState, change: DirectiveChangeMeta): void {
582	  const current = state.standard
583	  if (current === undefined) throw new Error('verification directive requires a current standard')
584	  if (change.standard.id !== current.id || change.standard.revision !== current.revision) {
585	    throw new Error('verification directive must reference the exact current standard revision')
586	  }
587	  /* v8 ignore next -- a current standard established by this fold always has a createdAt */
588	  if (state.createdAt === undefined) throw new Error('current standard fold lacks createdAt')
589	  if (change.issuedAt < state.createdAt) {
590	    throw new Error('verification directive cannot precede the current standard creation')
591	  }
592	  state.directivesIssued += 1
593	}
594	
595	/**
596	 * Apply one session event to the strict durable completion-standard fold.
597	 * @param state - mutable fold accumulator.
598	 * @param event - next event in sequence order.
599	 */
600	export function applyVerificationEvent(state: VerificationFoldState, event: SessionEvent): void {
601	  switch (event.type) {
602	    case 'verification/standard': {
603	      const change = decodeStandardChange(event.data)
604	      /* v8 ignore next -- the event's declared payload always identifies itself as a standard change */
605	      if (change === undefined) throw new Error(`verification change at session event ${event.seq} has an invalid kind`)
606	      applyStandardChange(state, change)
607	      return
608	    }
609	    case 'verification/relaxation': {
610	      const change = decodeRelaxationChange(event.data)
611	      /* v8 ignore next -- the event's declared payload always identifies itself as a relaxation */
612	      if (change === undefined) throw new Error(`verification change at session event ${event.seq} has an invalid kind`)
613	      applyRelaxationChange(state, change)
614	      return
615	    }
616	    case 'verification/run': {
617	      const change = decodeRunChange(event.data)
618	      /* v8 ignore next -- the event's declared payload always identifies itself as a run */
619	      if (change === undefined) throw new Error(`verification change at session event ${event.seq} has an invalid kind`)
620	      applyRunChange(state, change)
621	      return
622	    }
623	    case 'verification/certificate': {
624	      const change = decodeCertificateChange(event.data)
625	      /* v8 ignore next -- the event's declared payload always identifies itself as a certificate */
626	      if (change === undefined) throw new Error(`verification change at session event ${event.seq} has an invalid kind`)
627	      applyCertificateChange(state, change)
628	      return
629	    }
630	    case 'verification/directive': {
631	      const change = decodeDirectiveChange(event.data)
632	      /* v8 ignore next -- the event's declared payload always identifies itself as a directive */
633	      if (change === undefined) throw new Error(`verification change at session event ${event.seq} has an invalid kind`)
634	      applyDirectiveChange(state, change)
635	      return
636	    }
637	    default:
638	      // Non-verification events do not affect the completion-standard fold.
639	  }
640	}
641	
642	/**
643	 * Fold current completion-standard state from a contiguous session event log.
644	 * @param events - session events in sequence order.
645	 * @returns a fresh durable projection.
646	 */
647	export function foldVerification(events: readonly SessionEvent[]): FoldedVerification {
648	  const state = emptyVerificationFoldState()
649	  for (const event of events) applyVerificationEvent(state, event)
650	  return {
651	    ...state.standard === undefined ? {} : { standard: state.standard },
652	    ...state.certificate === undefined ? {} : { certificate: state.certificate },
653	    directivesIssued: state.directivesIssued,
654	    runsRecorded: state.runsRecorded,
655	    ...state.lastRun === undefined ? {} : { lastRun: state.lastRun },
656	    ...state.createdAt === undefined ? {} : { createdAt: state.createdAt },
657	    ...state.updatedAt === undefined ? {} : { updatedAt: state.updatedAt },
658	    ...state.lastRef === undefined ? {} : { lastRef: { ...state.lastRef } },
659	  }
660	}
