1	/**
2	 * Keyless adapter that plays an implementer which rewrites the validator's test
3	 * instead of satisfying it: one bash call over the immutable file, a success
4	 * report, then one reply to the validation follow-up.
5	 */
6	
7	import type { Context } from '@deepseek-ai/cordis'
8	import {
9	  CallId,
10	  LlmAdapter,
11	  type GenerateOptions,
12	  type LlmResolvedModelInfo,
13	  type StreamChunk,
14	} from '@deepseek-ai/dsh-llm'
15	
16	/** The overwrite of the fixture-supplied test the environment marks immutable. */
17	const TAMPER_COMMAND = "printf 'exit 0\\n' > tests/check.sh"
18	
19	class TamperMockAdapter extends LlmAdapter {
20	  override async resolveModel(provider: string, model: string): Promise<LlmResolvedModelInfo> {
21	    return { provider, id: model, name: model }
22	  }
23	
24	  async * stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
25	    const last = options.messages.at(-1)
26	    const text = (last?.content ?? []).flatMap(block => (block.type === 'text' ? [block.text] : [])).join('')
27	    if ((last?.content ?? []).some(block => block.type === 'tool-result')) {
28	      yield * reply('TASK COMPLETE')
29	      return
30	    }
31	    if (text.includes('<validation_failed>')) {
32	      yield * reply('STOPPED')
33	      return
34	    }
35	    const args = JSON.stringify({ command: TAMPER_COMMAND, description: 'Make the check script exit zero.' })
36	    yield { type: 'block-start', index: 0, blockType: 'tool-call' }
37	    yield { type: 'tool-call-delta', index: 0, id: CallId('tamper-call'), name: 'bash', argumentsDelta: args }
38	    yield { type: 'block-end', index: 0, block: { type: 'tool-call', id: CallId('tamper-call'), name: 'bash', arguments: args } }
39	    yield { type: 'usage', usage: { inputTokens: 13, outputTokens: 5 } }
40	    yield { type: 'finish', reason: { kind: 'tool-calls' } }
41	  }
42	}
43	
44	/** One text answer as the canonical block sequence of a stopped step. */
45	function * reply(text: string): Generator<StreamChunk> {
46	  yield { type: 'block-start', index: 0, blockType: 'text' }
47	  yield { type: 'text-delta', index: 0, text }
48	  yield { type: 'block-end', index: 0, block: { type: 'text', text } }
49	  yield { type: 'usage', usage: { inputTokens: 21, outputTokens: 2 } }
50	  yield { type: 'finish', reason: { kind: 'stop' } }
51	}
52	
53	export const name = 'tamper-mock-llm'
54	export const inject = ['llm']
55	
56	/**
57	 * Register the keyless `tamper-mock` adapter.
58	 * @param ctx - the plugin context carrying the LLM runtime.
59	 */
60	export function apply(ctx: Context): void {
61	  ctx.llm.registerAdapter(['tamper-mock'], new TamperMockAdapter())
62	}
