private resolveCaseTally(check: StandardCheck, result: CheckResult): CheckResult {
  const cases = result.cases
  if (cases === undefined) return result
  const reject = (reason: string): never => {
    throw new VerificationError(`result for check "${check.id}" ${reason}`, 'VERIFICATION_INVALID_RESULTS')
  }
  if (check.cases === undefined) reject('reports cases for a check that references none')
  if (cases.total !== check.cases.count || cases.weightTotal !== check.cases.weightTotal) {
    reject(`reports ${cases.total} cases of weight ${cases.weightTotal} against a reference of ${check.cases.count} of weight ${check.cases.weightTotal}`)
  }
