const caseBody: CheckCase = {
  id: CheckCaseId('reverse-empty'),
  weight: 2,
  input: { argv: [] },
  expected: { stdoutSha256: 'a'.repeat(64) },
  comparator: { channels: ['stdout'], normalizers: ['crlf'] },
